style.css:
/* تغيير لون الرسائل التي ترسلها أنت إلى البنفسجي */
div[role="row"] div[class*="x1n2onr3"] div[style*="background"] {
    background: linear-gradient(135deg, #a855f7, #6b21a8) !important;
    color: #ffffff !important;
}

/* كود عام لتغيير لون أي فقاعة رسالة خاصة بك إلى البنفسجي */
div[style*="background-color: rgb(0, 149, 246)"],
div[style*="background-color: rgb(55, 151, 240)"] {
    background-color: #8b5cf6 !important;
}
